from dataclasses import dataclass, field

@dataclass
class SessionState:
    user_id: str | None = None
    verified: bool = False
    cart: list = field(default_factory=list)

# billing_agent trusts and extends the SAME state object
def billing_agent(state: SessionState):
    assert state.verified, "identity must survive the handoff"
    state.cart.append("refund_issued")   # continues, doesn't reset
    return reply("Your refund is on the way.")

def route(handoff, state, max_hops=4):
    state.hops = getattr(state, "hops", 0) + 1
    if state.hops > max_hops:
        return Handoff(to="human", state=state)   # stop the ping-pong
    return AGENTS[handoff.to](state)

# specialist can hand BACK when done
def engineer_agent(state):
