from dataclasses import dataclass

@dataclass
class Handoff:
    to: str
    context: dict

def triage_agent(msg, ctx):
    if "refund" in msg:
        # transfer control + carry the goal forward
        return Handoff(to="billing_agent", context={"goal": msg})
    return f"triage: how can I help with '{msg}'?"

def billing_agent(msg, ctx):
    return f"billing: handling refund for goal='{ctx['goal']}'"

AGENTS = {"triage_agent": triage_agent, "billing_agent": billing_agent}

def run(msg):
    active, ctx = "triage_agent", {}
    out = AGENTS[active](msg, ctx)
    if isinstance(out, Handoff):        # control transfers
        active, ctx = out.to, out.context
        out = AGENTS[active](msg, ctx)  # specialist now drives
    return out

print(run("I need a refund"))

from dataclasses import dataclass, field

@dataclass
class State:
    verified: bool = False
    hops: int = 0

@dataclass
class Handoff:
    to: str

def triage(state):
    state.verified = True                 # established before handoff
    return Handoff(to="billing")

def billing(state):
    # trusts state carried across the boundary; hands back
    assert state.verified
    return Handoff(to="triage")            # would ping-pong forever

AGENTS = {"triage": triage, "billing": billing}

def run(start, state, max_hops=4):
    active = start
    while True:
        out = AGENTS[active](state)
        if not isinstance(out, Handoff):
            return out
        state.hops += 1
        if state.hops > max_hops:          # stop the ping-pong
            return f"escalated to human after {state.hops} hops (verified={state.verified})"
        active = out.to

print(run("triage", State()))

